begin
 perform 1 from public.yp_flavors where id in(select (value->>'id')::uuid from jsonb_array_elements(expected) where value->>'kind'='flavor') or id in(select (value->>'id')::uuid from jsonb_array_elements(extras)) for update;
 perform 1 from public.yp_products where id in(select (value->>'id')::uuid from jsonb_array_elements(expected) where value->>'kind'='product') for update;
 select count(*) into bad from jsonb_array_elements(expected) e
 left join (select 'flavor' as kind,id,name,sku,package_price,package_weight_grams,bundle_price,updated_at,active,deleted_at from public.yp_flavors union all select 'product',id,name,sku,package_price,package_weight_grams,bundle_price,updated_at,active,deleted_at from public.yp_products) t on t.id=(e->>'id')::uuid and t.kind=e->>'kind'
 where t.id is null or t.name is distinct from e->>'name' or t.sku is distinct from e->>'sku' or t.package_price is distinct from (e->>'old_price')::integer or t.package_weight_grams is distinct from (e->>'old_weight')::integer or t.bundle_price is distinct from (e->>'old_bundle')::integer or t.updated_at is distinct from (e->>'old_updated')::timestamptz or not t.active or t.deleted_at is not null;
 if bad<>0 then raise exception 'Catalog changed since audit snapshot: % rows. Nothing updated.',bad; end if;
 select count(*) into bad from jsonb_array_elements(extras) e left join public.yp_flavors f on f.id=(e->>'id')::uuid where f.id is null or f.name is distinct from e->>'name' or f.sku is distinct from e->>'sku' or f.package_price is distinct from (e->>'old_price')::integer or f.updated_at is distinct from (e->>'old_updated')::timestamptz;
 if bad<>0 then raise exception 'Extra flavors changed since audit snapshot. Nothing updated.'; end if;
 update public.yp_flavors f set package_price=(e->>'price')::integer,package_weight_grams=(e->>'weight')::integer,bundle_price=(e->>'price')::integer*5,updated_at=now() from jsonb_array_elements(expected) e where e->>'kind'='flavor' and f.id=(e->>'id')::uuid and (f.package_price is distinct from (e->>'price')::integer or f.package_weight_grams is distinct from (e->>'weight')::integer or f.bundle_price is distinct from (e->>'price')::integer*5);
 update public.yp_products p set package_price=(e->>'price')::integer,package_weight_grams=(e->>'weight')::integer,bundle_price=(e->>'price')::integer*5,updated_at=now() from jsonb_array_elements(expected) e where e->>'kind'='product' and p.id=(e->>'id')::uuid and (p.package_price is distinct from (e->>'price')::integer or p.package_weight_grams is distinct from (e->>'weight')::integer or p.bundle_price is distinct from (e->>'price')::integer*5);
 update public.yp_flavors f set active=false,available=false,updated_at=now() from jsonb_array_elements(extras) e where f.id=(e->>'id')::uuid;
end $audit$;
